type Status = 'loading' | 'empty' | 'ready' | 'refreshing' | 'error';
type Item = { id: string; title: string };
type Props = { status: Status; items: Item[]; error?: string; retry: () => void };

export function ItemWorkspace({ status, items, error, retry }: Props) {
  const initialLoad = status === 'loading' && items.length === 0;
  return <section aria-labelledby="items-heading" aria-busy={initialLoad || status === 'refreshing'}>
    <header><h1 id="items-heading">Items</h1>{status === 'refreshing' && <span role="status">Refreshing items…</span>}</header>
    {error && <div role="alert"><strong>Couldn’t update items.</strong><span> {error}</span><button onClick={retry}>Try again</button></div>}
    {initialLoad ? <p role="status">Loading items…</p> : items.length ? <ul>{items.map(item => <li key={item.id}>{item.title}</li>)}</ul> : <div><h2>No items yet</h2><p>Create an item to begin organizing your work.</p><button onClick={retry}>Refresh</button></div>}
  </section>;
}
